binhex.tex.body:
\ExplSyntaxOn
% 高位补零到宽 w: 数字位数 < w 时递归前缀 0 (可展开)
\cs_new:Npn \fixloop_pad:nn #1#2
  {
    \int_compare:nTF { \tl_count:n {#1} < #2 }
      { \fixloop_pad:nn { 0 #1 } {#2} }
      { #1 }
  }
\cs_new:Npn \fixloop_nbase:nnn #1#2#3
  {
    \exp_args:Ne \fixloop_pad:nn
      { \int_to_Base:nn { \int_eval:n {#3} } { \int_eval:n {#1} } }
      { #2 }
  }
\cs_new:Npn \nbinbased #1#2#3 { \fixloop_nbase:nnn { \fp_eval:n { round ( 2 ** #1 ) } } {#2} {#3} }
\cs_new:Npn \nhex #1#2 { \fixloop_nbase:nnn {16} {#1} {#2} }
\cs_new:Npn \noct #1#2 { \fixloop_nbase:nnn {8} {#1} {#2} }
\cs_new:Npn \ntetra #1#2 { \fixloop_nbase:nnn {4} {#1} {#2} }
\cs_new:Npn \nbinary #1#2 { \fixloop_nbase:nnn {2} {#1} {#2} }
\cs_new:Npn \hex #1 { \fixloop_nbase:nnn {16} {1} {#1} }
\cs_new:Npn \oct #1 { \fixloop_nbase:nnn {8} {1} {#1} }
\cs_new:Npn \tetra #1 { \fixloop_nbase:nnn {4} {1} {#1} }
\cs_new:Npn \binary #1 { \fixloop_nbase:nnn {2} {1} {#1} }
\ExplSyntaxOff
\endinput

